mapper.select:
select id,

from instance_slow_log
where app_id = #{appId}
  and execute_time >= #{startDate}
  and execute_time <= #{endDate}
order by execute_time desc

select concat(ip,":",port) as hostPort,count(*) as count
from instance_slow_log
where app_id = #{appId}
  and execute_time >= #{startDate}
  and execute_time <= #{endDate}
group by hostPort order by count desc

select app_id as appId, instance_id as instanceId, ip, port, count(*) as cnt
from instance_slow_log
where execute_time >= #{since}
group by app_id, instance_id, ip, port
order by cnt desc
limit #{limit}
